{
  "id": "ADR-JEV-0001",
  "title": "Keep the Jev core unchanged until its Rust replacement",
  "status": "Draft",
  "version": "0.1.0",
  "created": "2026-11-07",
  "last_updated": "2026-11-08",
  "owner": "Rand Lee",
  "supersedes": null,
  "superseded_by": null,
  "decision_date": "2026-11-07",
  "context": {
    "text": "judge-jev's Jev core (the batch command, request and result contracts,\nkey lookup and remote-judge consent) is copied from an existing\nimplementation, and a Rust implementation, exposed through PyO3 bindings or\na command-line interface (CLI), will replace that Python core. The problem\nis whether the Python core may change before then: any change to its\narchitecture or contracts is a change the Rust replacement must reproduce,\nor its callers break when the replacement lands.",
    "background": "",
    "problem_statement": ""
  },
  "decision": {
    "text": "The Jev core keeps its architecture and contracts unchanged. It changes\nonly to fix a defect, or to replace its run log with the sc-observability\nlogger (REQ-JEV-0008).",
    "chosen_approach": "",
    "key_principles": []
  },
  "rationale": {
    "text": "An unchanged core lets the Rust implementation replace it with no change\nto its callers.",
    "benefits": [],
    "trade_offs": []
  },
  "consequences": {
    "text": "",
    "positive": [
      "The Rust replacement is a drop-in."
    ],
    "negative": [
      "Improvements to the core wait for the Rust implementation."
    ],
    "neutral": []
  },
  "alternatives": {
    "text": "",
    "groups": [
      {
        "name": "Improve the Python core before the Rust replacement",
        "description": "Change the copied core's architecture or contracts now.",
        "pros": [],
        "cons": [],
        "why_rejected": "The Rust implementation could then not replace the core\nwithout a change to its callers."
      }
    ]
  },
