{
  "id": "ADR-JEV-0002",
  "title": "Query records through Raptor over local SQLite",
  "status": "Draft",
  "version": "0.1.0",
  "created": "2026-11-07",
  "last_updated": "2026-11-08",
  "owner": "Rand Lee",
  "supersedes": null,
  "superseded_by": null,
  "decision_date": "2026-11-07",
  "context": {
    "text": "judge-jev needs requirement records to judge, and their source is\nchanging: requirements move from Markdown files to a Dolt server as the\nsingle source of truth, with the Raptor command-line interface (CLI) as\nthe access path. Raptor owns the record schema and every conversion\n(REQ-JEV-0001). The problem is how judge-jev reads records so that neither\nthe move to Dolt nor a Raptor schema change breaks it.",
    "background": "",
    "problem_statement": ""
  },
  "decision": {
    "text": "judge-jev reads records only through Raptor, which queries a local SQLite\ndatabase: built on the fly from Markdown now, pulled from a Dolt branch\nlater.",
    "chosen_approach": "",
    "key_principles": []
  },
  "rationale": {
    "text": "Querying SQLite is the same work either way, so the source can change\nwithout touching judge-jev.",
    "benefits": [],
    "trade_offs": []
  },
  "consequences": {
    "text": "",
    "positive": [
      "The move to Dolt does not change judge-jev."
    ],
    "negative": [
      "judge-jev depends on Raptor's query contract; Raptor notifies judge-jev\nmaintenance before changing it."
    ],
    "neutral": []
  },
  "alternatives": {
    "text": "",
    "groups": [
      {
        "name": "Parse record Markdown directly",
        "description": "judge-jev reads the record Markdown files itself.",
        "pros": [],
        "cons": [],
        "why_rejected": "Raptor owns the schema and every conversion; a parser in\njudge-jev breaks when Raptor changes them (REQ-JEV-0001)."
      },
      {
        "name": "Query the record store with SQL directly",
        "description": "judge-jev runs its own SQL against the record store.",
        "pros": [],
        "cons": [],
        "why_rejected": "Raptor owns the schema; judge-jev's own queries break when\nRaptor changes it (REQ-JEV-0001)."
      }
    ]
  },
