{
  "id": "ADR-JEV-0003",
  "title": "Judge record quality instead of loosening the schema",
  "status": "Proposed",
  "version": "0.1.0",
  "created": "2026-11-07",
  "last_updated": "2026-11-08",
  "owner": "Rand Lee",
  "supersedes": null,
  "superseded_by": null,
  "decision_date": "2026-11-07",
  "context": {
    "text": "Raptor rejects records missing required sections, such as statements\nwritten as plain prose, so corpora with prose-only records do not import.\njudge-jev can judge only records with typed statements and criteria. The\nproblem is how such records get into a judgeable form: by loosening\nRaptor's schema to accept them, or by keeping it strict and explaining\nwhat to fix.",
    "background": "",
    "problem_statement": ""
  },
  "decision": {
    "text": "Raptor's schema stays strict. Raptor's import diagnostics explain why a\nrecord does not fit the schema; judge-jev's quality mode then explains why\nan imported record is not well written.",
    "chosen_approach": "",
    "key_principles": []
  },
  "rationale": {
    "text": "An explained rejection gets the document fixed; a looser schema stores\nrecords that cannot be judged.",
    "benefits": [],
    "trade_offs": []
  },
  "consequences": {
    "text": "",
    "positive": [
      "Every record judge-jev uses has typed statements and criteria."
    ],
    "negative": [
      "Corpora with prose-only records need editing before import, guided by\nthe import diagnostics."
    ],
    "neutral": []
  },
  "alternatives": {
    "text": "",
    "groups": [
      {
        "name": "Loosen Raptor's schema",
        "description": "Accept records missing required sections, such as\nprose-only statements.",
        "pros": [],
        "cons": [],
        "why_rejected": "A looser schema stores records that cannot be judged."
      }
    ]
