{
  "id": "ADR-JEV-0004",
  "title": "Code references are outside the first version",
  "status": "Draft",
  "version": "0.1.0",
  "created": "2026-11-07",
  "last_updated": "2026-11-08",
  "owner": "Rand Lee",
  "supersedes": null,
  "superseded_by": null,
  "decision_date": "2026-11-07",
  "context": {
    "text": "Records will eventually govern code as well as prompts, but selecting code\nneeds tree-sitter grammars, which sc-agent defines and which may not be\ncomplete yet. The problem is what the first version judges while those\ngrammars are unfinished.",
    "background": "",
    "problem_statement": ""
  },
  "decision": {
    "text": "The first version judges prompts, skills and task templates only. Code\nreferences come later through tree-sitter grammars that sc-agent defines;\njudge-jev never defines its own grammars. sc-agent's grammars may not be\ncomplete yet.",
    "chosen_approach": "",
    "key_principles": []
  },
  "rationale": {
    "text": "Prompt and task wording is the immediate risk; code selection needs the\ntree-sitter work first.",
    "benefits": [],
    "trade_offs": []
  },
  "consequences": {
    "text": "",
    "positive": [
      "The first version ships without a code-reference model."
    ],
    "negative": [
      "Code is not judged until the tree-sitter extension exists."
    ],
    "neutral": []
  },
  "alternatives": {
    "text": "",
    "groups": [
      {
        "name": "judge-jev defines its own tree-sitter grammars",
        "description": "Ship grammars inside judge-jev so code is judged now.",
        "pros": [],
        "cons": [],
        "why_rejected": "sc-agent owns the grammars so every consumer selects code\nthe same way (REQ-JEV-0203)."
      },
      {
        "name": "Line-range locations for code",
        "description": "Reference code by file line ranges instead of symbols.",
        "pros": [],
        "cons": [],
        "why_rejected": "Line ranges drift on every edit; symbols survive\n(REQ-JEV-0207)."
      }
    ]
