{
  "id": "ADR-JEV-0005",
  "title": "Pydantic models validate every JSON input",
  "status": "Draft",
  "version": "0.1.0",
  "created": "2026-11-07",
  "last_updated": "2026-11-08",
  "owner": "Rand Lee",
  "supersedes": null,
  "superseded_by": null,
  "decision_date": "2026-11-07",
  "context": {
    "text": "judge-jev reads JSON written by people and agents (quality trees, question\nsets, answers files, request streams), by Raptor (the import index) and by\nJev (responses). Quality trees will be varied thousands of times\n(REQ-JEV-0205). Hand-written type checks let fourteen input shapes crash\nthe script or fail only after a paid Jev call, found by review of PRs #13\nand #14. The problem is how to make every input either accepted, or refused\nwith the exact field, before the first call.",
    "background": "",
    "problem_statement": ""
  },
  "decision": {
    "text": "Every JSON input is parsed into a pydantic v2 model in strict mode before\nit is used, and code after parsing receives model instances, not\ndictionaries. Each model is the single definition of its input's shape.\nRules that span fields (a rule's choices are options of its question, a\n`goto` names a node, no cycle, a final rule without conditions) are model\nvalidators. `judge-jev validate` (REQ-JEV-0210) runs the same models\nwithout calling Jev. The JSON shapes of the Jev core's contracts do not\nchange (ADR-JEV-0001); only how they are checked does.",
    "chosen_approach": "",
    "key_principles": []
  },
  "rationale": {
    "text": "One model per input replaces scattered checks that each had to anticipate\nevery wrong type, and pydantic reports the field path of every refusal.",
    "benefits": [],
    "trade_offs": []
  },
  "consequences": {
    "text": "",
    "positive": [
      "Every refusal names the field and the rule it breaks.",
      "Tree authors check a variation with `judge-jev validate` before a run."
    ],
    "negative": [
      "pydantic (with its compiled core) becomes a dependency, pinned in the\nscript's PEP 723 header and in CI.",
      "Refusal wording follows pydantic's messages."
    ],
    "neutral": []
  },
  "alternatives": {
    "text": "",
    "groups": [
      {
        "name": "Keep hand-written checks",
        "description": "Extend the `isinstance` checks for each new crash found.",
        "pros": [],
        "cons": [],
        "why_rejected": "Each new shape needs a new check; review of #13 and #14\nfound fourteen that were missed."
      },
      {
        "name": "JSON Schema validated by `jsonschema`",
        "description": "One schema file per input, validated at load.",
        "pros": [],
        "cons": [],
        "why_rejected": "Rules that span fields stay hand-written, and code after\nvalidation still handles untyped dictionaries."
      }
    ]
  },
